insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('02919210-1247-4b0c-a2b6-fee19cf55364','zh-tw','1577-1577-designated-driver-jingle','1577-1577代駕廣告歌','把迴文式電話號碼寫成歌曲、深植代駕業界印象的廣告歌','2008年前後，代駕業者1577-1577推出以「頭尾相同的電話號碼1577-1577代駕」為主題的廣告歌，靠洗腦旋律把號碼本身刻進大眾腦海。由姜成範等人演唱的這首歌甚至被登錄上音源平台，廣為流傳。後來喜劇演員李洙根出任代言人，讓這首廣告歌更加知名。','2008年前後1577-1577代駕電視廣告。','作為以迴文電話號碼為賣點的廣告歌行銷案例引用。',null,array['앞뒤가 똑같은 전화번호','1577-1577 대리운전 CM송'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;

-- knk2hsye  trend_score=324.26  우정의 무대 그리운 어머니
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('d5fbbcff-805a-4141-b203-6109d21823e9','zh-tw','friendship-stage-missed-mother','《友情的舞台》思念的媽媽','軍營勞軍演出中母子相見感人單元','1990年7月起，KBS《友情的舞台》固定在節目最後段落播放插曲〈思念的媽媽〉，思念的母親現身舞台、與兒子戲劇性重逢的畫面，每次播出都讓觀眾淚崩。至今節目片段仍被剪輯轉發，「媽媽想念的時候」開場也成為懷舊象徵。','KBS《友情的舞台》單元(1990年代)。','描述感人重逢場面時作為比喻引用。',null,array['그리운 어머니','엄마가 보고플 때','우정의 무대 그리운 어머니'],'[{"text": "這段重逢畫面完全是《友情的舞台》等級的催淚", "situation": "聊天訊息"}, {"text": "聽到〈思念的媽媽〉眼淚都要忍不住了", "situation": "社群留言"}]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
